import React from "react";
import { useLocation, Route, Switch } from "react-router-dom";

import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";
import routes from "routes.js";

import sidebarImage from "assets/img/my-background1.jpg";

function Admin() {
  const [image] = React.useState(sidebarImage);
  const [color] = React.useState("black");
  const [hasImage] = React.useState(true);
  const [overlayOpen, setOverlayOpen] = React.useState(false);

  const location = useLocation();
  const mainPanel = React.useRef(null);

  const getRoutes = (routes) =>
    routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => <prop.component {...props} />}
            key={key}
          />
        );
      }
      return null;
    });

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    if (mainPanel.current) mainPanel.current.scrollTop = 0;
    setOverlayOpen(false); // 🔥 เปลี่ยนหน้าแล้วปิดเมนู
  }, [location]);

  return (
    <>
      <div className="wrapper">
        <div
          className="main-panel"
          ref={mainPanel}
          style={{ width: "100%" }}
        >
          <div className="content">
            <Switch>{getRoutes(routes)}</Switch>
          </div>
          <Footer />
        </div>
      </div>

      {/* 🔘 Floating Menu Button */}
      <button
        onClick={() => setOverlayOpen(!overlayOpen)}
        style={{
          position: "fixed",
          top: "20px",
          right: "20px",
          zIndex: 5000,
          width: "48px",
          height: "48px",
          borderRadius: "50%",
          border: "none",
          background: "#1DC7EA",
          color: "#fff",
          fontSize: "22px",
          cursor: "pointer",
        }}
      >
        ☰
      </button>

      {/* ⬛ Backdrop */}
      {overlayOpen && (
        <div
          onClick={() => setOverlayOpen(false)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.45)",
            zIndex: 3000,
          }}
        />
      )}

      {/* 📋 Overlay Sidebar (ของเดิม 100%) */}
      <div
        style={{
          position: "fixed",
          top: 0,
          right: overlayOpen ? 0 : "-260px",
          width: "260px",
          height: "100vh",
          zIndex: 4000,
          transition: "right 0.3s ease",
          left: "auto", // 🔥 สำคัญมาก แก้อาการไปโผล่ซ้าย
        }}
      >
        <Sidebar
          color={color}
          image={hasImage ? image : ""}
          routes={routes}
          onLinkClick={() => setOverlayOpen(false)}
        />
      </div>
    </>
  );
}

export default Admin;
